import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - nextGeneration", () => {
  it.todo("should return no cells for an empty generation");
  it.todo("should kill a single live cell with no neighbors");
  it.todo("should kill two adjacent cells that each have only one neighbor (underpopulation)");
  it.todo("should keep a live cell with three neighbors alive (survival)");
  it.todo("should kill a live cell with four neighbors (overpopulation)");
  it.todo("should bring a dead cell with exactly three neighbors to life (reproduction)");
  it.todo("should keep a block unchanged (still life)");
  it.todo("should turn a vertical blinker into a horizontal blinker including negative coordinates (oscillator)");
});

